// Price list downloads carry the technical information: specifications (e.g. capacity, CCA, layout for batteries), cross
// reference codes by brand (e.g. SAB for batteries, GUD for filters) and OE numbers as extra columns, and a Vehicles sheet
// for a one-range download. Pricing app (all downloads, and a Technical info sheet in the costing workbook) and Customers > Prices.
const fs = require("fs");
function edit(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [from, to] of pairs) {
    const n = s.split(from).length - 1;
    if (n !== 1) { console.error(`${file}: expected the text once, found it ${n} times: ${from.slice(0, 70)}`); process.exit(1); }
    s = s.replace(from, () => to);
  }
  fs.writeFileSync(file, s);
  console.log(file + ": updated");
}
